css:
.container {
  width: 100%;
  height: 100%;
  background: linear-gradient(
      45deg,
      orange 25%,
      transparent 25%,
      transparent 75%,
      orange 75%,
      orange
    ),
    linear-gradient(
      45deg,
      orange 25%,
      transparent 25%,
      transparent 75%,
      orange 75%,
      orange
    );
  background-size: 20px 20px;
  background-position: 0 0, 10px 10px;
}
